 9 | /*
10 |  * OwnershipNFTs is a simple interface for tracking ownership of
11 |  * positions in the Seawater Stylus contract.
12 |  */
13 | contract OwnershipNFTs is IERC721Metadata {
14 |     ISeawaterAMM immutable public SEAWATER;
15 | 
16 |     /**
17 |      * @notice TOKEN_URI to set as the default token URI for every NFT
18 |      * @dev immutable in practice (not set anywhere)
19 |      */
20 |     string public TOKEN_URI;
21 | 
22 |     /// @notice name of the NFT, set by the constructor
23 |     string public name;
24 | 
25 |     /// @notice symbol of the NFT, set during the constructor
26 |     string public symbol;
27 | 
28 |     /**
29 |      * @notice getApproved that can spend the id of the tokens given
30 |      * @dev required in the NFT spec and we simplify the use here by
31 |      *      naming the storage slot as such
32 |      */
33 |     mapping(uint256 => address) public getApproved;
34 | 
35 |     /// @notice isApprovedForAll[owner][spender] == true if `spender` can spend any of `owner`'s NFTs
36 |     mapping(address => mapping(address => bool)) public isApprovedForAll;
37 | 
38 |     constructor(
39 |         string memory _name,
40 |         string memory _symbol,
41 |         string memory _tokenURI,
42 |         ISeawaterAMM _seawater
43 |     ) {
44 |         name = _name;
45 |         symbol = _symbol;
46 |         TOKEN_URI = _tokenURI;
47 |         SEAWATER = _seawater;
48 |     }
49 | 
50 |     /**
51 |      * @notice ownerOf a NFT given by looking it up with the tracked Seawater contract
52 |      * @param _tokenId to look up
53 |      */
54 |     function ownerOf(uint256 _tokenId) public view returns (address) {
55 |         (bool ok, bytes memory rc) = address(SEAWATER).staticcall(abi.encodeWithSelector(
56 |             SEAWATER.positionOwnerD7878480.selector,
57 |             _tokenId
58 |         ));
59 |         require(ok, "position owner revert");
60 |         (address owner) = abi.decode(rc, (address));
61 |         return owner;
62 |     }
63 | 
64 |     /**
65 |      * @notice _onTransferReceived by calling the callback `onERC721Received`
66 |      *         in the recipient if they have codesize > 0. if the callback
67 |      *         doesn't return the selector, revert!
68 |      * @param _sender that did the transfer
69 |      * @param _from owner of the NFT that the sender is transferring
